using System.ComponentModel;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using ResearchAgent;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the AI:ApiKey configuration value or the OPENAI_API_KEY environment variable.");

var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddSingleton<Notebook>();

builder.Services.AddChatClient(b => b
    .UseLogging()
    .UseOpenAIChatClient(modelId, new OpenAI.OpenAIClient(apiKey)));

builder.Logging.SetMinimumLevel(LogLevel.Warning);

var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var notebook = host.Services.GetRequiredService<Notebook>();

var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research agent. When given a topic, you search the web for relevant information,
        take notes on key findings, and then produce a concise summary.

        Follow this workflow:
        1. Search the web for the topic using varied queries to get broad coverage.
        2. Take notes on each important finding using the note-taking tool.
        3. After gathering enough information (at least 2-3 searches), review your notes and
           provide a final summary to the user.

        Always cite your sources when summarizing.
        """,
    name: "ResearchAgent",
    description: "An agent that researches topics by searching the web and summarizing findings.",
    tools: [
        AIFunctionFactory.Create(WebSearchTool.SearchWebAsync),
        AIFunctionFactory.Create(notebook.SaveNoteAsync),
        AIFunctionFactory.Create(notebook.GetNotesAsync),
    ]);

Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║       Research Agent (MAF + MEAI)    ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine();
Console.WriteLine("Enter a topic to research (or 'quit' to exit):");

var session = await agent.CreateSessionAsync();

while (true)
{
    Console.Write("\n> ");
    var input = Console.ReadLine();

    if (string.IsNullOrWhiteSpace(input) || input.Equals("quit", StringComparison.OrdinalIgnoreCase))
    {
        break;
    }

    notebook.Clear();

    Console.WriteLine("\nResearching...\n");

    try
    {
        var response = await agent.RunAsync(
            input,
            session,
            new ChatClientAgentRunOptions(new ChatOptions
            {
                Temperature = 0f,
                MaxOutputTokens = 2048,
            }));

        Console.WriteLine("───── Summary ─────");
        Console.WriteLine(response.Text);
        Console.WriteLine("────────────────────");

        if (response.Usage is { } usage)
        {
            Console.WriteLine(
                $"\n[Tokens — input: {usage.InputTokenCount}, output: {usage.OutputTokenCount}, total: {usage.TotalTokenCount}]");
        }
    }
    catch (Exception ex)
    {
        Console.WriteLine($"Error: {ex.Message}");
    }
}

Console.WriteLine("Goodbye!");

