using System.ComponentModel;
using System.Text.Json;
using Microsoft.Extensions.AI;

namespace ResearchAgent;

/// <summary>
/// Provides a web search tool that the agent can invoke to find information.
/// Uses a simulated search engine for demonstration; swap the implementation
/// for a real search API (e.g., Bing Search) in production.
/// </summary>
internal static class WebSearchTool
{
    private static readonly Dictionary<string, List<SearchResult>> SimulatedResults = new(StringComparer.OrdinalIgnoreCase)
    {
        ["quantum computing"] =
        [
            new("Quantum Computing Basics - MIT", "https://mit.edu/quantum",
                "Quantum computing uses qubits that can exist in superposition, enabling parallel computation. " +
                "Key algorithms include Shor's (factoring) and Grover's (search). Current leaders include IBM, Google, and IonQ."),
            new("Google Quantum AI Milestone", "https://blog.google/quantum",
                "In 2024, Google's Willow chip achieved quantum error correction below threshold for the first time, " +
                "a critical milestone for building practical, fault-tolerant quantum computers."),
            new("Quantum Computing Applications", "https://nature.com/quantum-apps",
                "Potential applications include drug discovery, materials science, cryptography, " +
                "financial modeling, and optimization problems. Current NISQ-era devices have 50-1000+ qubits."),
        ],
        ["artificial intelligence"] =
        [
            new("State of AI 2025", "https://aiindex.stanford.edu",
                "AI systems now match or exceed human performance on many benchmarks. " +
                "Large language models have transformed natural language processing, code generation, and reasoning tasks."),
            new("AI Safety and Alignment", "https://openai.com/safety",
                "AI safety research focuses on alignment, interpretability, and robustness. " +
                "Key challenges include hallucination, bias, and ensuring AI systems behave as intended."),
            new("AI in Industry", "https://mckinsey.com/ai-report",
                "AI adoption in enterprises grew 50% year-over-year. Top use cases include " +
                "customer service automation, predictive analytics, and content generation."),
        ],
        ["climate change"] =
        [
            new("IPCC 2025 Report", "https://ipcc.ch/report",
                "Global temperatures have risen 1.2°C above pre-industrial levels. " +
                "Without significant emissions reductions, warming could reach 2.5-3°C by 2100."),
            new("Renewable Energy Progress", "https://iea.org/renewables",
                "Solar and wind now account for 30% of global electricity. Battery storage costs have dropped 90% since 2010. " +
                "Investment in clean energy reached $1.8 trillion in 2024."),
            new("Climate Tech Innovations", "https://nature.com/climate-tech",
                "Emerging solutions include direct air capture, green hydrogen, enhanced geothermal, " +
                "and next-generation nuclear. Carbon removal capacity needs to scale 1000x by 2050."),
        ],
    };

    [Description("Searches the web for information on a given query. Returns a list of results with titles, URLs, and snippets.")]
    public static Task<string> SearchWebAsync(
        [Description("The search query to look up on the web.")] string query)
    {
        // Find results by checking if any key is contained in the query (or vice versa)
        var results = SimulatedResults
            .Where(kv => query.Contains(kv.Key, StringComparison.OrdinalIgnoreCase)
                         || kv.Key.Contains(query, StringComparison.OrdinalIgnoreCase))
            .SelectMany(kv => kv.Value)
            .ToList();

        if (results.Count == 0)
        {
            // Return generic results for unrecognized queries
            results =
            [
                new($"Wikipedia: {query}", $"https://en.wikipedia.org/wiki/{Uri.EscapeDataString(query)}",
                    $"Overview article covering the key aspects and history of {query}. " +
                    "This topic spans multiple disciplines and has seen significant recent developments."),
                new($"Latest Research on {query}", $"https://scholar.google.com/search?q={Uri.EscapeDataString(query)}",
                    $"Recent academic papers and research findings related to {query}. " +
                    "Multiple peer-reviewed studies published in the last year explore new approaches and findings."),
            ];
        }

        var output = results.Select(r => new
        {
            r.Title,
            r.Url,
            r.Snippet,
        });

        return Task.FromResult(JsonSerializer.Serialize(output, new JsonSerializerOptions { WriteIndented = true }));
    }

    private sealed record SearchResult(string Title, string Url, string Snippet);
}

using System.ComponentModel;
using System.Text;

namespace ResearchAgent;

/// <summary>
/// Provides a note-taking tool that lets the agent save and retrieve research notes.
/// Notes persist across tool calls within a single research session.
/// </summary>
internal sealed class Notebook
{
    private readonly List<Note> _notes = [];

    [Description("Saves a research note with a topic label and content. Use this to record important findings from web searches.")]
    public Task<string> SaveNoteAsync(
        [Description("A short label for the note (e.g., 'quantum error correction').")] string topic,
        [Description("The content of the note summarizing what was found.")] string content,
        [Description("The source URL where this information was found.")] string sourceUrl)
    {
        var note = new Note(topic, content, sourceUrl, DateTime.UtcNow);
        _notes.Add(note);
        return Task.FromResult($"Note #{_notes.Count} saved: '{topic}'");
    }

    [Description("Retrieves all research notes taken so far. Use this before writing a final summary to review findings.")]
    public Task<string> GetNotesAsync()
    {
        if (_notes.Count == 0)
        {
            return Task.FromResult("No notes have been taken yet.");
        }

        var sb = new StringBuilder();
        for (var i = 0; i < _notes.Count; i++)
        {
            var note = _notes[i];
            sb.AppendLine($"--- Note #{i + 1}: {note.Topic} ---");
            sb.AppendLine(note.Content);
            sb.AppendLine($"Source: {note.SourceUrl}");
